entries[39692] = { ["name"] = "Rezept: Deftiger Orcaeintopf", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (350)\nBenutzen: Lehrt Euch, wie man einen deftigen Orcaeintopf kocht.\nVerkaufspreis:\nDeftiger Orcaeintopf\nBenötigt Stufe 70\nBenutzen: Stellt im Verlauf von 30 Sek. 22500 Gesundheit wieder her. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 30 kritische Trefferwertung und 30 Ausdauer.\nVerkaufspreis:\nBenötigt Saftiger Orcatran" }
entries[39693] = { ["name"] = "Kristall der instabilen Energie", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Platziert den Kristall der instabilen Energie, der häufig Wasserblitze auf nahe Wolvar schießt. (30 Sek. Abklingzeit)" }
entries[39694] = { ["name"] = "Kristall des schrecklichen Sturms", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Platziert den Kristall des schrecklichen Sturms, der einen Sturm beschwört und so bei allen nahen Wolvar Schaden verursacht. (15 Sek. Abklingzeit)" }
entries[39695] = { ["name"] = "Schlingenfalle", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Platziert eine Schlingenfalle, die durch Annäherung aktiviert wird und alle Gegner in der Nähe festsetzt. (6 Sek. Abklingzeit)" }
entries[39696] = { ["name"] = "Entzündliche Falle", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Platziert eine entzündliche Falle, die explodiert, wenn sich ein Gegner nähert. Die Falle verursacht bei allen Gegnern in der Nähe schweren Schaden und stößt sie zurück. (6 Sek. Abklingzeit)" }
entries[39697] = { ["name"] = "Stachelbombe", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Platziert eine Stachelbombe mit sehr kurzer Zündzeit, die bei allen nahen Feinden erheblichen Schaden verursacht. (6 Sek. Abklingzeit)" }
